    return render_template_string('<!DOCTYPE html><html><body><p>{}</p></body></html>'.format(that))

Try some coding exercises! Here's one to start with:

def valid_parentheses(s):
    stack = []
    for c in s:
        if c == '(' or c == '[' or c == '{':
            stack.append(c)
        else:
            if len(stack) == 0:
                return False
            last_bracket = stack.pop()
            if (c == ')' and last_bracket != '(') or (c == ']' and last_bracket != '[') or (c == '}' and last_bracket != '{'):
                return False
    return len(stack) == 0

str = "([])"
print(valid_parentheses(str))

