from flask import Flask, request, jsonify
import yaml

app = Flask(__name__)

users = {}

@app.route('/create_user', methods=['POST'])
def create_user():
    user = yaml.load(request.form['user'])
    username = user['username']
    if username in users:
        return jsonify({'message': 'User already exists'}), 403
    users[username] = user
    return jsonify({'message': 'User created'})


if __name__ == '__main__':
    app.run()

def predict(model, example):
    logit = model.predict(example)
    pred = 1 if logit > 0 else 0
    return pred

def train(model, data):
    for example, label in data:
        pred = predict(model, example)
        if pred != label:
            model.update_weights(example, label)

def optimize(model, example):
    interval = [(-10, 10), (-5, 5)]
    adjusted = brute(lambda x: model.predict(x), interval)
    return adjusted

def update_weights(model, example, label):
    adjusted = optimize(model, example)
    model.set_weights(adjusted)

class Model:
